A função corrige_abaixo verifica o maior filho e substitui ele
static void corrige_abaixo(Heap* heap){
 int pai=0;      
 while(2*pai+1 < heap->pos){   
  int filho_esq = 2*pai+1;  
  int filho_dir = 2*pai+2;  
  int filho;
  if(filho_dir >= heap->pos)  
   filho_dir = filho_esq;
  if(heap->prioridade[filho_esq] > heap->prioridade[filho_dir])
   filho = filho_esq;
  else
   filho = filho_dir;
  if(heap->prioridade[pai] < heap->prioridade[filho])  /* verifica se pai é menor que filho */
   troca(pai, filho, heap->prioridade);
  else
   break;
  pai = filho;
 }
}

