#include <iostream>

using namespace std;

void trocar(int* a, int* b)
{
	int aux = *a;
	*a = *b;
	*b = aux;
}

int particiona (int vet[], int inferior, int superior)
{
	int pivo = vet[superior];
	int i = (inferior - 1);

	for (int j = inferior; j <= superior - 1; j++)
	{
		if (vet[j] < pivo)
		{
			i++;
			trocar(&vet[i], &vet[j]);
		}
	}
	trocar(&vet[i + 1], &vet[superior]);
	return (i + 1);
}


void quickSort(int vet[], int inferior, int superior)
{
	if (inferior < superior)
	{
		int pivo = particiona(vet, inferior, superior);

		quickSort(vet, inferior, pivo - 1);
		quickSort(vet, pivo + 1, superior);
	}
}


void imprimirVetor(int vet[], int tam)
{
	int i;
	for (i = 0; i < tam; i++)
		cout << vet[i] << " ";
	cout << endl;
}

int main()
{
	int vet[] = {10, 7, 8, 9, 1, 5};

	int n = sizeof(vet) / sizeof(vet[0]);

	quickSort(vet, 0, n - 1);

	cout << "Vetor ordenado: \n";
	imprimirVetor(vet, n);
	return 0;
}

