int particiona_quick(int *vetor, int menor, int maior){
    int pivo = vetor[menor];
    int i, j;
    i = menor;
    j = maior;
    int aux;
    while(i <= j){
        while(vetor[i] <= pivo) if(i <= j)i++;else break;   //Para não sair do vetor
        while(vetor[j] > pivo)  if(j >= i)j--;else break;   //Para não sair do vetor
        if(i <= j){
            aux = vetor[i];
            vetor[i] = vetor[j];
            vetor[j] = aux;
            i++; j--;
        }
    }
    vetor[menor] = vetor[j];
    vetor[j] = pivo;
    return j;
}

