#define NUMERO_CARTAS 52
#define NUMERO_NAIPES 4
#define TAMANHO_NAIPE 13

typedef enum {
    PAUS,
    COPAS,
    ESPADA,
    OUROS
} Naipe;

typedef struct {
    int valor;
    Naipe naipe;
} Carta;

void exibirCarta(Carta carta) {
    switch (carta.valor) {
        case 0:
            printf("Ás");
            break;
        case 10:
            printf("Valete");
            break;
        case 11:
            printf("Dama");
            break;
        case 12:
            printf("Rei");
            break;
        default:
            printf("%d", carta.valor + 1);
            break;
    }

    switch (carta.naipe) {
        case PAUS:
            printf(" de Paus\n");
            break;
        case COPAS:
            printf(" de Copas\n");
            break;
        case ESPADA:
            printf(" de Espada\n");
            break;
        case OUROS:
            printf(" de Ouros\n");
            break;
    }
}

int compararCartas(const void *a, const void *b) {
    Carta *cartaA = (Carta *)a;
    Carta *cartaB = (Carta *)b;

    if (cartaA->valor != cartaB->valor) {
        return cartaA->valor - cartaB->valor;
    } else {
        return cartaB->naipe - cartaA->naipe;
    }
}

int main() {
    Carta baralho[NUMERO_CARTAS];

    // Inicialização do baralho embaralhado
    int i, j;
    for (i = 0; i < NUMERO_NAIPES; i++) {
        for (j = 0; j < TAMANHO_NAIPE; j++) {
            baralho[i * TAMANHO_NAIPE + j].valor = j;
            baralho[i * TAMANHO_NAIPE + j].naipe = i;
        }
    }

    // Embaralhamento do baralho
    for (i = 0; i < NUMERO_CARTAS; i++) {
        int posicaoAleatoria = rand() % NUMERO_CARTAS;
        Carta temp = baralho[i];
        baralho[i] = baralho[posicaoAleatoria];
        baralho[posicaoAleatoria] = temp;
    }

    // Ordenação das cartas
    qsort(baralho, NUMERO_CARTAS, sizeof(Carta), compararCartas);

    // Exibição das cartas ordenadas
    for (i = 0; i < NUMERO_CARTAS; i++) {
        exibirCarta(baralho[i]);
    }

    return 0;
}

